mapper.select:
SELECT 
FROM room_message m
LEFT JOIN users u ON u.user_id = m.user_id
WHERE m.room_id = #{roomId}
ORDER BY m.message_id DESC
LIMIT #{limit}

SELECT 
FROM room_message m
LEFT JOIN users u ON u.user_id = m.user_id
WHERE m.room_id = #{roomId}
  AND m.message_id < #{beforeId}
ORDER BY m.message_id DESC
LIMIT #{limit}

SELECT 
FROM room_message m
LEFT JOIN users u ON u.user_id = m.user_id
WHERE m.room_id = #{roomId}
  AND m.message_id > #{afterId}
ORDER BY m.message_id ASC
LIMIT #{limit}

mapper.update:
UPDATE room_participant
SET last_read_message_id = #{messageId}
WHERE room_id = #{roomId}
  AND user_id = #{userId}
  AND (last_read_message_id IS NULL OR last_read_message_id < #{messageId})
  AND #{messageId} <= (SELECT COALESCE(MAX(message_id), 0) FROM room_message WHERE room_id = #{roomId})

UPDATE room_participant
SET last_read_message_id = (SELECT MAX(message_id) FROM room_message WHERE room_id = #{roomId})
WHERE room_id = #{roomId}
  AND user_id = #{userId}
